mapper.insert:
insert into cm_inbox_broadcast_targets (
    id, broadcast_id, user_id, message_id, status, error_message, next_retry_at
) values (
    #{id}, #{broadcastId}, #{userId}, #{messageId}, #{status}, #{errorMessage},
    if(#{status} = 'retrying', date_add(now(), interval 5 minute), null)
)

mapper.select:
select b.id, b.scope, b.tier, b.mode, b.template_code as templateCode, b.locale, b.subject_type as subjectType, b.target_count as targetCount, b.success_count as successCount, b.failure_count as failureCount, b.created_at as createdAt, b.updated_at as updatedAt, u.user_name as staffUserName from cm_inbox_broadcasts b left join sys_user u on cast(u.user_id as char) = b.staff_user_id
b.staff_user_id = #{staffUserId}
and b.mode = #{mode}
and b.template_code = #{templateCode}
order by b.created_at desc, b.id desc

select d.id, d.user_id as userId, d.message_id as messageId, d.mode, d.template_code as templateCode, d.locale, d.subject_type as subjectType, d.subject_id as subjectId, d.status, d.error_message as errorMessage, d.retry_count as retryCount, d.next_retry_at as nextRetryAt, d.created_at as createdAt, d.updated_at as updatedAt, u.account_name as accountName, su.user_name as staffUserName from cm_inbox_single_dispatches d left join cm_users u on u.id = d.user_id left join sys_user su on cast(su.user_id as char) = d.staff_user_id
d.staff_user_id = #{staffUserId}
and d.user_id = #{userId}
and d.mode = #{mode}
and d.status = #{status}
order by d.created_at desc, d.id desc

select d.id, d.staff_user_id as staffUserId, d.payload_json as payloadJson
from cm_inbox_single_dispatches d
where d.status = 'retrying' and d.retry_count < #{maxAttempts}
  and d.next_retry_at <= now()
order by d.next_retry_at limit #{batchSize}

mapper.update:
update cm_inbox_broadcast_targets
set status = 'failure', error_message = #{errorMessage}, next_retry_at = null
where id = #{id}

mapper.select:
select id, user_id as userId, template_code as templateCode,
       variables_json as variablesJson, subject_id as subjectId, dedupe_key as dedupeKey
from cm_inbox_system_failures
where status = 'pending' and retry_count < #{maxAttempts}
  and next_retry_at <= now()
order by next_retry_at limit #{batchSize}

mapper.update:
update cm_inbox_system_failures
set status = 'failure', error_message = #{errorMessage}, next_retry_at = null
where id = #{id}
